<!doctype html><html><head><meta charset="utf-8"><title>{{ $payment->receipt_number }}</title><style>body{font-family:Arial,sans-serif;margin:40px;color:#111}h1{margin:0 0 4px}table{width:100%;border-collapse:collapse;margin-top:25px}th,td{border:1px solid #ccc;padding:9px;text-align:left}.right{text-align:right}.total{font-size:20px;font-weight:bold}.sign{margin-top:90px;display:flex;justify-content:space-between}@media print{.no-print{display:none}}</style></head><body onload="window.print()"><div class="no-print"><button onclick="window.print()">Print</button></div><h1>PAYMENT RECEIPT</h1><div>Tech Team — IT Supplies, Services & Support</div><hr><p><strong>Receipt No:</strong> {{ $payment->receipt_number }}<br><strong>Date:</strong> {{ $payment->payment_date->format('d-M-Y') }}<br><strong>Customer:</strong> {{ $payment->customer->company_name }}<br><strong>Payment Method:</strong> {{ $payment->payment_method }}<br><strong>Reference:</strong> {{ $payment->reference ?: '—' }}</p><table><thead><tr><th>Invoice</th><th class="right">Amount Allocated</th></tr></thead><tbody>@foreach($payment->allocations as $allocation)<tr><td>{{ $allocation->invoice->invoice_number }}</td><td class="right">PKR {{ number_format($allocation->amount,2) }}</td></tr>@endforeach</tbody><tfoot><tr><td class="total">Total Received</td><td class="right total">PKR {{ number_format($payment->amount,2) }}</td></tr></tfoot></table>@if($payment->notes)<p><strong>Notes:</strong> {{ $payment->notes }}</p>@endif<div class="sign"><div>Received By: __________________</div><div>Authorized Signature: __________________</div></div></body></html>
